css:
:root {
  --washer-title: #0E5B67;
  --washer-subtitle: #728DA5;

  --washer-line: #4B7DA6;
  --washer-arrow: #176A95;

  --washer-stage-border: #4B83A7;
  --washer-stage-number: #1C5A6B;
  --washer-stage-label: #246975;

  --washer-endpoint-text: #306897;
  --washer-separator: #C8DAE5;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.washer-header-widget {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
}

.washer-header-svg {
  display: block;
  width: 100%;
  height: 100%;

  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  shape-rendering: geometricPrecision;
}

/* Encabezado */
.washer-title {
  fill: var(--washer-title);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0;
}

.washer-subtitle {
  fill: var(--washer-subtitle);
  font-size: 21px;
  font-weight: 400;
  letter-spacing: 0;
}

/* Entrada y salida */
.washer-endpoint {
  fill: url("#washer-endpoint-fill");
  stroke: none;
}

.washer-endpoint-text {
  fill: var(--washer-endpoint-text);
  font-size: 15px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Recorrido horizontal */
.washer-flow-line {
  fill: none;
  stroke: var(--washer-line);
  stroke-width: 2.5;
  stroke-linecap: round;
}

.washer-flow-arrows {
  fill: var(--washer-arrow);
  stroke: none;
}

/* Identificadores circulares */
.washer-stage-circle {
  fill: url("#washer-stage-fill");
  stroke: var(--washer-stage-border);
  stroke-width: 2.2;
}

.washer-stage-number {
  fill: var(--washer-stage-number);
  font-size: 23px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-anchor: middle;
  dominant-baseline: central;
}

.washer-stage-label {
  fill: var(--washer-stage-label);
  font-size: 20px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Separadores discretos */
.washer-separators {
  fill: none;
  stroke: var(--washer-separator);
  stroke-width: 1.2;
  stroke-dasharray: 3 4;
}

js:
"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 2 / LAVADORA";

  let titleElement = null;
  let svg = null;
  let latestWidget = null;

  function render(w) {
    if (!titleElement || !svg) return;

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    const title = name || DEFAULT_TITLE;

    // Muestra exactamente el Nombre asignado en el inspector.
    titleElement.textContent = title;

    svg.setAttribute(
      "aria-label",
      title +
      ". Vista general de los subprocesos. " +
      "Entrada de fibra, 01 Pre-estiramiento, " +
      "02 Estiramiento principal, 03 Lavado, " +
      "04 Preparación, hacia secador."
    );
  }

  /*
   * Actualiza el título cuando el software comunica
   * un cambio en el Nombre del widget.
   *
   * No utiliza variables del PLC.
   */
  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    titleElement = document.querySelector(".washer-title");
    svg = document.querySelector(".washer-header-svg");

    if (!titleElement || !svg) return;

    render(latestWidget || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
